// The text of src/help/registry.generated.ts, from the keys of the article
// files. Pure; scripts/help-registry.mjs reads the files and writes the result.

const identifierOf = (key) => `article_${key.replaceAll(/[/-]/g, '_')}`

/** The text of the registry for the given keys, formatted as oxfmt keeps it. */
export function renderRegistry(keys) {
  const sorted = keys.toSorted()
  return [
    '// Generated by scripts/help-registry.mjs from the files in ./articles.',
    '// Do not edit it. Add or remove an article file, then run `pnpm help:registry`.',
    "import type { RegisteredArticle } from './catalog'",
    ...sorted.map(
      (key) => `import ${identifierOf(key)} from './articles/${key}'`,
    ),
    '',
    'export const HELP_REGISTRY: readonly RegisteredArticle[] = [',
    ...sorted.map((key) => `  ['${key}', ${identifierOf(key)}],`),
    ']',
    '',
  ].join('\n')
}
